package com.crms.entity;import com.crms.enums.ApplicationStatus;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"student_id","job_id"})) public class Application{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Student student;@ManyToOne(optional=false)@JoinColumn(name="job_id")private JobPosting job;@Enumerated(EnumType.STRING)private ApplicationStatus status=ApplicationStatus.PENDING;private Instant createdAt=Instant.now();public Long getId(){return id;}public Student getStudent(){return student;}public void setStudent(Student v){student=v;}public JobPosting getJob(){return job;}public void setJob(JobPosting v){job=v;}public ApplicationStatus getStatus(){return status;}public void setStatus(ApplicationStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}}
